import React, { useState, useEffect } from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { Myhostlocalapi } from './../Myhostlocalapi';
import { 
  Coffee, 
  Table as TableIcon, 
  Calendar as CalendarIcon, 
  Download, 
  CalendarDays,
  X,
  Check,
  FileSpreadsheet,
  Info
} from 'lucide-react';

export default function UserScheduleView() {
  const [user] = useState(JSON.parse(localStorage.getItem('user')) || {});
  const [employees, setEmployees] = useState([]);
  const [schedules, setSchedules] = useState({});
  const [viewMode, setViewMode] = useState('table');

  // --- State สำหรับเวรเที่ยง ---
  const [isLunchModalOpen, setIsLunchModalOpen] = useState(false);
  const [lunchDuties, setLunchDuties] = useState({});

  const today = new Date();
  const [selectedYear, setSelectedYear] = useState(today.getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(today.getMonth());
  const [selectedDay, setSelectedDay] = useState(today.getDate());

  const totalDaysInMonth = new Date(selectedYear, selectedMonth + 1, 0).getDate();
  const daysInMonth = Array.from({ length: totalDaysInMonth }, (_, i) => i + 1);

  const thaiDayNames = ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'];
  const thaiFullDayNames = ['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'];
  const monthsListTH = [
    'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
    'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
  ];
  const monthsList = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];

  const dayNames = daysInMonth.map(day => {
    const d = new Date(selectedYear, selectedMonth, day);
    return thaiDayNames[d.getDay()];
  });

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedMonth, selectedYear]);

  const [highlightedEmpCode, setHighlightedEmpCode] = useState(null);
  const [highlightedDay, setHighlightedDay] = useState(null);

  const handleEmpClick = (empCode) => {
    setHighlightedEmpCode((prev) => (prev === empCode ? null : empCode));
  };

  const handleDayClick = (day) => {
    setHighlightedDay((prev) => (prev === day ? null : day));
  };

  const fetchData = async () => {
    try {
      const headers = { 'ngrok-skip-browser-warning': '69420' };
      const empRes = await axios.get(`${Myhostlocalapi}/api/employees?department_id=${user?.department_id}`, { headers });
      const schedRes = await axios.get(`${Myhostlocalapi}/api/schedules?month=${selectedMonth + 1}&year=${selectedYear}`, { headers });

      setEmployees(empRes.data);

      const map = {};
      schedRes.data.forEach(item => {
        const day = new Date(item.WorkDate).getDate();
        if (!map[item.EmpCode]) map[item.EmpCode] = {};
        map[item.EmpCode][day] = item.ShiftCode;
      });
      setSchedules(map);

      try {
        const lunchRes = await axios.get(`${Myhostlocalapi}/api/lunch-duties?month=${selectedMonth + 1}&year=${selectedYear}`, { headers });
        const lunchMap = {};
        lunchRes.data.forEach(item => {
          const dateKey = item.DutyDate.split('T')[0];
          if (!lunchMap[dateKey]) lunchMap[dateKey] = [];
          lunchMap[dateKey].push(item.EmpCode);
        });
        setLunchDuties(lunchMap);
      } catch (lErr) {
        console.error("Error fetching lunch duties:", lErr);
      }

    } catch (err) {
      console.error("Error fetching data from server:", err);
    }
  };

  const getShiftForEmpDay = (empCode, day) => {
    return schedules[empCode]?.[day] || 'null';
  };

  const hasLunchDuty = (empCode, day) => {
    const formattedMonth = String(selectedMonth + 1).padStart(2, '0');
    const formattedDay = String(day).padStart(2, '0');
    const dateStr = `${selectedYear}-${formattedMonth}-${formattedDay}`;
    return (lunchDuties[dateStr] || []).includes(empCode);
  };

  const getEmployeesByShift = (shiftCodes) => {
    return employees.filter(emp => {
      const shift = getShiftForEmpDay(emp.EmpCode, selectedDay);
      return shiftCodes.includes(shift);
    });
  };

  const officeEmployees = getEmployeesByShift(['E11', 'F13']);
  const wfhEmployees = getEmployeesByShift(['ZE02']);
  const offEmployees = getEmployeesByShift(['OFF']);

  const getFirstDayOffset = (startFromMonday = true) => {
    const firstDay = new Date(selectedYear, selectedMonth, 1).getDay();
    if (startFromMonday) {
      return firstDay === 0 ? 6 : firstDay - 1;
    }
    return firstDay;
  };

  const shiftColors = {
    'E11': { bg: '#ecfdf5', text: '#065f46', border: '#a7f3d0' },
    'F13': { bg: '#f0fdfa', text: '#0f766e', border: '#99f6e4' },
    'ZE02': { bg: '#f0f9ff', text: '#0369a1', border: '#bae6fd' },
    'OFF': { bg: '#fff1f2', text: '#be123c', border: '#fecdd3' },
    'null': { bg: '#ffffff', text: '#94a3b8', border: '#e2e8f0' }
  };

  const exportToExcel = () => {
    let csv = '\uFEFF'; // UTF-8 BOM สำหรับ Excel ภาษาไทย
    const headers = ['รหัสพนักงาน', 'ชื่อ-นามสกุล'];
    daysInMonth.forEach(d => {
      headers.push(`วันที่ ${d} (${dayNames[d - 1]})`);
    });
    headers.push('ชม.ทำงานรวม', 'วันทำงาน Office', 'WFH', 'วันหยุด (OFF)', 'เวรเที่ยง (ครั้ง)');
    csv += headers.map(h => `"${h}"`).join(',') + '\r\n';

    employees.forEach(emp => {
      const row = [`"${emp.EmpCode || ''}"`, `"${emp.FullName || ''}"`];
      let workCount = 0;
      let wfhCount = 0;
      let offCount = 0;
      let lunchCount = 0;

      daysInMonth.forEach(d => {
        const shift = getShiftForEmpDay(emp.EmpCode, d);
        const displayShift = shift === 'null' ? '' : shift;
        row.push(`"${displayShift}"`);

        if (shift === 'E11' || shift === 'F13') workCount++;
        else if (shift === 'ZE02') wfhCount++;
        else if (shift === 'OFF') offCount++;

        if (hasLunchDuty(emp.EmpCode, d)) lunchCount++;
      });

      const totalHours = (workCount + wfhCount) * 8;
      row.push(totalHours, workCount, wfhCount, offCount, lunchCount);
      csv += row.join(',') + '\r\n';
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', `ตารางกะ_${monthsListTH[selectedMonth]}_${selectedYear + 543}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportToPDF = async () => {
    const printDate = new Date();
    const formattedPrintDate = `${printDate.getDate()} ${monthsListTH[printDate.getMonth()]} ${printDate.getFullYear() + 543} ${String(printDate.getHours()).padStart(2, '0')}:${String(printDate.getMinutes()).padStart(2, '0')}`;
    const periodText = `1 - ${totalDaysInMonth} ${monthsListTH[selectedMonth]} ${selectedYear + 543}`;

    const printElement = document.createElement('div');
    printElement.style.position = 'absolute';
    printElement.style.left = '-9999px';
    printElement.style.top = '-9999px';
    printElement.style.width = '1000px';
    printElement.style.padding = '12px 15px';
    printElement.style.backgroundColor = '#ffffff';

    if (viewMode === 'table') {
      printElement.innerHTML = `
        <div style="font-family: 'Kanit', sans-serif; color: #000;">
          <div style="display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 8px;">
            <div>
              <div style="font-size: 16px; font-weight: bold; color: #1e3a8a;">ตารางการปฏิบัติงานของพนักงาน IT</div>
            </div>
            <div style="text-align: center;">
              <div style="font-size: 13px; font-weight: bold;">ประจำวันที่ ${periodText}</div>
            </div>
            <div style="text-align: right; font-size: 10px; color: #475569;">
              <div>วันที่พิมพ์ : ${formattedPrintDate}</div>
            </div>
          </div>

          <table style="width: 100%; border-collapse: collapse; font-size: 9px; text-align: center; border: 1px solid #000;">
            <thead>
              <tr style="background-color: #f1f5f9;width: 100%;height: 50px;">
                <th style="border: 1px solid #000; padding: 3px 2px; width: 50px; vertical-align: middle;">รหัส</th>
                <th style="border: 1px solid #000; padding: 3px 2px; width: 120px; text-align: left; vertical-align: middle;">ชื่อ - นามสกุล</th>
                ${daysInMonth.map((d, i) => `
                  <th style="border: 1px solid #000; padding: 2px 1px; vertical-align: middle;">
                    <div style="font-size: 8px; color: ${dayNames[i] === 'ส' || dayNames[i] === 'อา' ? '#dc2626' : '#000'}; line-height: 1.2;">${dayNames[i]}</div>
                    <div style="line-height: 1.2;">${d}</div>
                  </th>
                `).join('')}
                <th style="border: 1px solid #000; padding: 3px 2px; width: 35px; vertical-align: middle;">ชม.</th>
              </tr>
            </thead>
            <tbody>
              ${employees.map(emp => {
                let totalHours = 0;
                return `
                  <tr>
                    <td style="border: 1px solid #000; padding: 3px 2px 5px 2px; font-size: 8.5px; vertical-align: middle;">${emp.EmpCode || '-'}</td>
                    <td style="border: 1px solid #000; padding: 3px 2px 5px 2px; text-align: left; font-weight: 500; font-size: 8.5px; vertical-align: middle;">${emp.FullName}</td>
                    ${daysInMonth.map(d => {
                      const shift = getShiftForEmpDay(emp.EmpCode, d);
                      if (shift !== 'OFF' && shift !== 'null') totalHours += 8;
                      const displayShift = shift === 'null' ? '' : shift;
                      return `<td style="border: 1px solid #000; padding: 3px 1px 5px 1px; font-size: 8px; vertical-align: middle;">${displayShift}</td>`;
                    }).join('')}
                    <td style="border: 1px solid #000; padding: 3px 1px 5px 1px; font-weight: bold; font-size: 8px; vertical-align: middle;">${totalHours > 0 ? `${totalHours}H` : '-'}</td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      `;
    } else {
      const sunOffset = getFirstDayOffset(false);
      let totalOffCount = 0;
      let totalWfhCount = 0;

      employees.forEach(emp => {
        daysInMonth.forEach(d => {
          const shift = getShiftForEmpDay(emp.EmpCode, d);
          if (shift === 'OFF') totalOffCount++;
          if (shift === 'ZE02') totalWfhCount++;
        });
      });

      printElement.innerHTML = `
        <div style="font-family: 'Kanit', sans-serif; color: #000;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
            <div style="font-size: 11px; font-weight: bold;">
              Off = ${totalOffCount} วัน | WFH = ${totalWfhCount} วัน
            </div>
            <div style="font-size: 16px; font-weight: bold; text-align: center;">
              ${monthsListTH[selectedMonth]} ${selectedYear + 543} ${monthsList[selectedMonth]}.${selectedYear}
            </div>
            <div style="font-size: 10px; color: #475569;">
              วันที่พิมพ์ : ${formattedPrintDate}
            </div>
          </div>

          <div style="display: grid; grid-template-columns: repeat(7, 1fr); border: 1px solid #000;">
            ${thaiFullDayNames.map(day => `
              <div style="border: 1px solid #000; padding: 3px; text-align: center; font-weight: bold; background-color: #f8fafc; font-size: 10px;">
                ${day}
              </div>
            `).join('')}

            ${Array.from({ length: sunOffset }).map(() => `
              <div style="border: 1px solid #000; min-height: 52px; background-color: #f8fafc;"></div>
            `).join('')}

            ${daysInMonth.map(d => `
              <div style="border: 1px solid #000; min-height: 52px; padding: 2px 3px; box-sizing: border-box; background-color: #fff;">
                <div style="text-align: right; font-weight: bold; font-size: 10px; line-height: 1.2; margin-bottom: 2px;">${d}</div>
                <div style="font-size: 7.5px; display: flex; flex-direction: column; gap: 1px;">
                  ${employees.map(emp => {
                    const shift = getShiftForEmpDay(emp.EmpCode, d);
                    if (shift === 'null') return '';
                    return `
                      <div style="display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px dashed #cbd5e1; padding: 1px 0;">
                        <span style="white-space: nowrap; overflow: visible; max-width: 75px; line-height: 1.4; padding-bottom: 1px;">${emp.FullName.split(' ')[0]}</span>
                        <b style="color: ${shift === 'OFF' ? '#dc2626' : shift === 'ZE02' ? '#0284c7' : '#059669'}; font-size: 7px; line-height: 1.4;">${shift}</b>
                      </div>
                    `;
                  }).join('')}
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    document.body.appendChild(printElement);

    try {
      const canvas = await html2canvas(printElement, {
        scale: 2,
        useCORS: true,
        logging: false
      });

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('landscape', 'mm', 'a4');
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();
      const imgWidth = pdfWidth;
      const imgHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, imgWidth, Math.min(imgHeight, pdfHeight));
      pdf.save(`Shift_Schedule_${monthsList[selectedMonth]}_${selectedYear}_${viewMode.toUpperCase()}.pdf`);
    } catch (error) {
      console.error("Export PDF error:", error);
      alert("เกิดข้อผิดพลาดในการสร้างไฟล์ PDF");
    } finally {
      document.body.removeChild(printElement);
    }
  };

  return (
    <div className="main-viewport">
      {/* Top Header Card */}
      <div className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200/80 shadow-sm mb-6">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                <CalendarDays className="w-4 h-4" />
              </span>
              <h1 className="text-xl sm:text-2xl font-bold text-slate-900 tracking-tight">
                ตารางงานประจำเดือน (Schedule Overview)
              </h1>
            </div>
            <p className="text-xs sm:text-sm text-slate-500 mt-1 pl-10">
              {monthsList[selectedMonth].toUpperCase()} {selectedYear} • แผนก: <span className="font-semibold text-slate-700">{user?.department_name || 'IT'}</span>
            </p>
          </div>

          {/* Action Buttons */}
          <div className="flex flex-wrap items-center gap-2">
            {/* Lunch Duty */}
            <button
              onClick={() => setIsLunchModalOpen(true)}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold bg-amber-50 text-amber-700 hover:bg-amber-100 border border-amber-200 transition-all shadow-xs"
            >
              <Coffee className="w-3.5 h-3.5" />
              <span>ตารางเวรเที่ยง</span>
            </button>

            {/* View Mode Toggle */}
            <button
              onClick={() => setViewMode(viewMode === 'table' ? 'calendar' : 'table')}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 transition-all shadow-xs"
            >
              {viewMode === 'table' ? (
                <>
                  <CalendarIcon className="w-3.5 h-3.5" />
                  <span>Calendar View</span>
                </>
              ) : (
                <>
                  <TableIcon className="w-3.5 h-3.5" />
                  <span>Table View</span>
                </>
              )}
            </button>

            {/* Export Excel */}
            <button
              onClick={exportToExcel}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold bg-emerald-600 hover:bg-emerald-700 text-white transition-all shadow-xs"
              title="ดาวน์โหลดตารางกะเป็นไฟล์ Excel / CSV"
            >
              <FileSpreadsheet className="w-3.5 h-3.5" />
              <span>Export Excel</span>
            </button>

            {/* Export PDF */}
            <button
              onClick={exportToPDF}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200 border border-slate-200 transition-all shadow-xs"
            >
              <Download className="w-3.5 h-3.5" />
              <span>Export PDF</span>
            </button>
          </div>
        </div>
      </div>

      {/* 1. Main View: Table Mode */}
      {viewMode === 'table' ? (
        <div className="bg-white rounded-2xl p-4 sm:p-6 border border-slate-200/80 shadow-sm mb-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4 pb-3 border-b border-slate-100">
            <h3 className="font-bold text-slate-900 text-base flex items-center gap-2">
              <TableIcon className="w-4 h-4 text-indigo-600" /> ตารางกะพนักงานรายวัน
            </h3>

            {/* Month/Year Filter */}
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => {
                  const now = new Date();
                  setSelectedMonth(now.getMonth());
                  setSelectedYear(now.getFullYear());
                }}
                className="px-2.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold transition-colors cursor-pointer"
                title="กลับสู่เดือนปัจจุบัน"
              >
                วันนี้
              </button>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                {monthsListTH.map((m, idx) => (
                  <option key={m} value={idx}>{m}</option>
                ))}
              </select>

              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(Number(e.target.value))}
                className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                {[2025, 2026, 2027].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Schedule Table */}
          <div className="overflow-x-auto rounded-xl border border-slate-200">
            <table className="w-full border-collapse text-center text-xs">
              <thead>
                <tr className="bg-slate-50 text-slate-600">
                  <th className="sticky left-0 z-20 bg-slate-50 px-4 py-2.5 text-left font-bold border-b border-r border-slate-200 min-w-[130px] shadow-xs">
                    ชื่อพนักงาน
                  </th>

                  {daysInMonth.map((d, i) => {
                    const isColHighlighted = d === highlightedDay;
                    const isWeekend = dayNames[i] === 'ส' || dayNames[i] === 'อา';
                    return (
                      <th
                        key={d}
                        onClick={() => handleDayClick(d)}
                        className={`p-1.5 min-w-[38px] cursor-pointer border-b border-r border-slate-200/80 transition-colors ${
                          isColHighlighted ? 'bg-indigo-100/70' : isWeekend ? 'bg-rose-50/40 text-rose-600' : 'bg-slate-50'
                        }`}
                      >
                        <div className="flex flex-col items-center">
                          <span className={`text-[10px] ${isWeekend ? 'text-rose-500 font-bold' : 'text-slate-400'}`}>
                            {dayNames[i]}
                          </span>
                          <span className="font-bold text-slate-800 text-xs">{d}</span>
                        </div>
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {employees.map(emp => {
                  const isRowHighlighted = emp.EmpCode === highlightedEmpCode;

                  return (
                    <tr key={emp.EmpCode} className="hover:bg-slate-50/50 transition-colors">
                      <td
                        onClick={() => handleEmpClick(emp.EmpCode)}
                        className={`sticky left-0 z-10 px-4 py-2 text-left font-medium border-b border-r border-slate-200 cursor-pointer whitespace-nowrap shadow-xs transition-colors ${
                          isRowHighlighted ? 'bg-indigo-50 font-bold text-indigo-900' : 'bg-white text-slate-800'
                        }`}
                      >
                        {emp.FullName}
                      </td>

                      {daysInMonth.map(d => {
                        const currentShift = getShiftForEmpDay(emp.EmpCode, d);
                        const shiftKey = String(currentShift);
                        const activeColor = shiftColors[shiftKey] || { bg: '#ffffff', text: '#94a3b8', border: '#e2e8f0' };

                        const isColHighlighted = d === highlightedDay;
                        const isIntersection = isRowHighlighted && isColHighlighted;
                        const isLunch = hasLunchDuty(emp.EmpCode, d);

                        return (
                          <td
                            key={d}
                            className={`p-1 border-b border-r border-slate-100 relative ${
                              isIntersection ? 'bg-indigo-100/90' : isRowHighlighted || isColHighlighted ? 'bg-slate-50' : ''
                            }`}
                          >
                            {isLunch && (
                              <span
                                title="เวรเที่ยง"
                                className="absolute top-1 left-1 w-1.5 h-1.5 rounded-full bg-rose-500 ring-2 ring-white"
                              />
                            )}

                            <div
                              style={{
                                backgroundColor: activeColor.bg,
                                color: activeColor.text,
                                borderColor: activeColor.border
                              }}
                              className="w-full py-1 px-1 font-bold text-[11px] rounded-lg border text-center select-none shadow-2xs"
                            >
                              {currentShift === 'null' ? '-' : currentShift}
                            </div>
                          </td>
                        );
                      })}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        /* Calendar View Mode */
        <div className="bg-white rounded-2xl p-4 sm:p-6 border border-slate-200/80 shadow-sm mb-6">
          <div className="flex justify-between items-center mb-4 pb-3 border-b border-slate-100">
            <h3 className="font-bold text-slate-900 text-base flex items-center gap-2">
              <CalendarIcon className="w-4 h-4 text-indigo-600" /> ปฏิทินแสดงรายวัน
            </h3>
            <div className="flex gap-2">
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm font-medium"
              >
                {monthsListTH.map((m, idx) => (
                  <option key={m} value={idx}>{m}</option>
                ))}
              </select>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(Number(e.target.value))}
                className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm font-medium"
              >
                {[2025, 2026, 2027].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="overflow-x-auto">
            <div className="grid grid-cols-7 gap-2 min-w-[700px]">
              {['จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์', 'อาทิตย์'].map((day, idx) => (
                <div
                  key={day}
                  className={`py-2 text-center font-bold text-xs rounded-lg ${
                    idx >= 5 ? 'bg-rose-50 text-rose-600' : 'bg-slate-50 text-slate-600'
                  }`}
                >
                  {day}
                </div>
              ))}

              {Array.from({ length: getFirstDayOffset(true) }).map((_, idx) => (
                <div key={`empty-${idx}`} className="bg-slate-50/50 rounded-xl border border-slate-100 min-h-[90px]"></div>
              ))}

              {daysInMonth.map(d => (
                <div key={d} className="bg-white rounded-xl border border-slate-200 p-2 min-h-[90px] flex flex-col justify-between">
                  <div className="font-bold text-xs text-slate-700 pb-1 border-b border-slate-100">
                    {d}
                  </div>
                  <div className="space-y-1 overflow-y-auto max-h-[85px] pt-1">
                    {employees.map(emp => {
                      const currentShift = getShiftForEmpDay(emp.EmpCode, d);
                      const shiftKey = String(currentShift);
                      const activeColor = shiftColors[shiftKey] || { bg: '#ffffff', text: '#94a3b8' };

                      return (
                        <div key={emp.EmpCode} className="flex items-center justify-between text-[11px] gap-1">
                          <span className="truncate flex-1 text-slate-600 font-medium">
                            {emp.FullName.split(' ')[0]}
                          </span>
                          <span
                            style={{ backgroundColor: activeColor.bg, color: activeColor.text }}
                            className="text-[10px] font-bold rounded px-1.5 py-0.5"
                          >
                            {currentShift === 'null' ? '-' : currentShift}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* 2. Daily Grid View */}
      <div className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200/80 shadow-sm">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-5 pb-3 border-b border-slate-100">
          <h3 className="font-bold text-slate-900 text-base">
            Daily Breakdown (สรุปตามวันที่เลือก)
          </h3>
          <div className="flex items-center gap-2">
            <span className="text-xs text-slate-500 font-medium">เลือกวันที่:</span>
            <select
              value={selectedDay}
              onChange={(e) => setSelectedDay(Number(e.target.value))}
              className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm font-semibold text-slate-700"
            >
              {daysInMonth.map(d => (
                <option key={d} value={d}>วันที่ {d} {monthsListTH[selectedMonth]}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* Card: All Employees */}
          <div className="bg-slate-50/80 rounded-2xl p-4 border border-slate-200/80">
            <div className="font-bold text-xs text-slate-700 bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-2xs mb-3 flex items-center justify-between">
              <span>พนักงานทั้งหมด</span>
              <span className="text-indigo-600 font-bold">{employees.length} คน</span>
            </div>
            <div className="space-y-1.5 max-h-56 overflow-y-auto">
              {employees.map(emp => (
                <div key={emp.EmpCode} className="text-xs text-slate-600 font-medium py-1 px-2 bg-white rounded-lg border border-slate-100 truncate">
                  {emp.FullName}
                </div>
              ))}
            </div>
          </div>

          {/* Card: Office */}
          <div className="bg-emerald-50/60 rounded-2xl p-4 border border-emerald-200/80">
            <div className="font-bold text-xs text-emerald-800 bg-emerald-100/70 px-3 py-1.5 rounded-lg mb-3 flex items-center justify-between">
              <span>Office (E11 / F13)</span>
              <span>{officeEmployees.length} คน</span>
            </div>
            <div className="space-y-1.5 max-h-56 overflow-y-auto">
              {officeEmployees.length > 0 ? (
                officeEmployees.map(emp => {
                  const shift = getShiftForEmpDay(emp.EmpCode, selectedDay);
                  return (
                    <div key={emp.EmpCode} className="text-xs font-semibold py-1.5 px-2 bg-white rounded-lg border border-emerald-100 text-emerald-800 flex justify-between items-center shadow-2xs">
                      <span className="truncate">{emp.FullName}</span>
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-700 font-bold">{shift}</span>
                    </div>
                  );
                })
              ) : (
                <div className="text-center text-xs text-slate-400 py-4">ไม่มีพนักงานเข้าออฟฟิศ</div>
              )}
            </div>
          </div>

          {/* Card: WFH */}
          <div className="bg-sky-50/60 rounded-2xl p-4 border border-sky-200/80">
            <div className="font-bold text-xs text-sky-800 bg-sky-100/70 px-3 py-1.5 rounded-lg mb-3 flex items-center justify-between">
              <span>Work From Home (ZE02)</span>
              <span>{wfhEmployees.length} คน</span>
            </div>
            <div className="space-y-1.5 max-h-56 overflow-y-auto">
              {wfhEmployees.length > 0 ? (
                wfhEmployees.map(emp => (
                  <div key={emp.EmpCode} className="text-xs font-semibold py-1.5 px-2 bg-white rounded-lg border border-sky-100 text-sky-800 truncate shadow-2xs">
                    {emp.FullName}
                  </div>
                ))
              ) : (
                <div className="text-center text-xs text-slate-400 py-4">ไม่มีพนักงาน WFH</div>
              )}
            </div>
          </div>

          {/* Card: OFF */}
          <div className="bg-rose-50/60 rounded-2xl p-4 border border-rose-200/80">
            <div className="font-bold text-xs text-rose-800 bg-rose-100/70 px-3 py-1.5 rounded-lg mb-3 flex items-center justify-between">
              <span>วันหยุด (OFF)</span>
              <span>{offEmployees.length} คน</span>
            </div>
            <div className="space-y-1.5 max-h-56 overflow-y-auto">
              {offEmployees.length > 0 ? (
                offEmployees.map(emp => (
                  <div key={emp.EmpCode} className="text-xs font-semibold py-1.5 px-2 bg-white rounded-lg border border-rose-100 text-rose-800 truncate shadow-2xs">
                    {emp.FullName}
                  </div>
                ))
              ) : (
                <div className="text-center text-xs text-slate-400 py-4">ไม่มีพนักงานหยุด</div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Shift Legend & Code Explanations */}
      <div className="bg-white rounded-2xl p-4 sm:p-5 border border-slate-200/80 shadow-sm mb-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-3 border-b border-slate-100">
          <div className="text-xs font-bold text-slate-800 flex items-center gap-1.5">
            <Info className="w-4 h-4 text-indigo-600" />
            <span>คำอธิบายรหัสกะและสัญลักษณ์ (Shift Legend)</span>
          </div>
          <span className="text-[11px] text-slate-400">สัญลักษณ์และเวลาทำงานมาตรฐานของแผนก</span>
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2.5 pt-3 text-xs">
          <div className="flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80">
            <span className="w-6 h-6 rounded-lg bg-rose-100 text-rose-700 flex items-center justify-center font-bold text-[11px]">☕</span>
            <div>
              <div className="font-bold text-rose-700">OFF</div>
              <div className="text-[10px] text-slate-500">วันหยุดประจำสัปดาห์</div>
            </div>
          </div>
          <div className="flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80">
            <span className="w-6 h-6 rounded-lg bg-sky-100 text-sky-700 flex items-center justify-center font-bold text-[11px]">🏠</span>
            <div>
              <div className="font-bold text-sky-700">ZE02 / WFH</div>
              <div className="text-[10px] text-slate-500">ทำงานที่บ้าน</div>
            </div>
          </div>
          <div className="flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80">
            <span className="w-6 h-6 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-bold text-[11px]">⏰</span>
            <div>
              <div className="font-bold text-indigo-700">F13</div>
              <div className="text-[10px] text-slate-500">09:00 - 18:00 น.</div>
            </div>
          </div>
          <div className="flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80">
            <span className="w-6 h-6 rounded-lg bg-emerald-100 text-emerald-700 flex items-center justify-center font-bold text-[11px]">☀️</span>
            <div>
              <div className="font-bold text-emerald-700">E11 / F1</div>
              <div className="text-[10px] text-slate-500">08:00 - 17:00 น.</div>
            </div>
          </div>
          <div className="flex items-center gap-2 p-2 rounded-xl bg-slate-50 border border-slate-200/80">
            <span className="w-6 h-6 rounded-lg bg-purple-100 text-purple-700 flex items-center justify-center font-bold text-[11px]">🍱</span>
            <div>
              <div className="font-bold text-purple-700">เวรเที่ยง</div>
              <div className="text-[10px] text-slate-500">สลับพัก 13:00 - 14:00</div>
            </div>
          </div>
        </div>
      </div>

      {/* --- Modal ปฏิทินแสดงเวรเที่ยง (Read-Only) --- */}
      {isLunchModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-4xl max-h-[90vh] overflow-y-auto p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100">
              <div>
                <h2 className="font-bold text-slate-900 text-lg flex items-center gap-2">
                  <Coffee className="w-5 h-5 text-amber-600" /> ตารางเวรเที่ยง ({monthsListTH[selectedMonth]} {selectedYear + 543})
                </h2>
                <p className="text-xs text-slate-500">
                  รายชื่อผู้มีเวรเที่ยงในแต่ละวัน
                </p>
              </div>
              <button
                onClick={() => setIsLunchModalOpen(false)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="overflow-x-auto rounded-xl border border-slate-200">
              <div className="grid grid-cols-7 gap-1 bg-slate-100 min-w-[650px] p-1">
                {['จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์', 'อาทิตย์'].map((day, idx) => (
                  <div 
                    key={day} 
                    className={`p-2 text-center font-bold text-xs rounded-lg ${
                      idx >= 5 ? 'bg-rose-100 text-rose-700' : 'bg-white text-slate-700'
                    }`}
                  >
                    {day}
                  </div>
                ))}

                {Array.from({ length: getFirstDayOffset(true) }).map((_, idx) => (
                  <div key={`empty-modal-${idx}`} className="bg-slate-50/60 rounded-lg min-h-[90px]" />
                ))}

                {daysInMonth.map(d => {
                  const formattedMonth = String(selectedMonth + 1).padStart(2, '0');
                  const formattedDay = String(d).padStart(2, '0');
                  const dateStr = `${selectedYear}-${formattedMonth}-${formattedDay}`;
                  const dutyEmps = lunchDuties[dateStr] || [];

                  return (
                    <div key={d} className="bg-white rounded-lg p-2 min-h-[90px] flex flex-col justify-between border border-slate-200/80">
                      <div className="font-bold text-xs text-slate-700 mb-1">
                        {d}
                      </div>

                      <div className="space-y-1 overflow-y-auto max-h-[80px]">
                        {employees.map(emp => {
                          const isSelected = dutyEmps.includes(emp.EmpCode);
                          if (!isSelected) return null;
                          return (
                            <div
                              key={emp.EmpCode}
                              className="px-1.5 py-0.5 rounded text-[11px] font-bold bg-rose-500 text-white flex items-center justify-between"
                            >
                              <span className="truncate">
                                {emp.FullName.split(' ')[0]}
                              </span>
                              <Check className="w-3 h-3" />
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="flex justify-end pt-2">
              <button
                onClick={() => setIsLunchModalOpen(false)}
                className="px-5 py-2 rounded-xl bg-slate-800 hover:bg-slate-900 text-white font-semibold text-xs sm:text-sm"
              >
                ปิดหน้าต่าง
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
