import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Myhostlocalapi } from './../Myhostlocalapi';
import { 
  Users, 
  UserPlus, 
  Search, 
  Pencil, 
  Trash2, 
  X, 
  AlertTriangle,
  Bell,
  BellOff,
  Clock
} from 'lucide-react';

const API_BASE_URL = `${Myhostlocalapi}/api`;

export default function EmployeeManagement() {
  const [user] = useState(JSON.parse(localStorage.getItem('user')) || null);
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // States สำหรับควบคุม Modal Pop-up
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  // States สำหรับเก็บ Form Data และการเลือก Item
  const [selectedEmp, setSelectedEmp] = useState(null);
  const [formData, setFormData] = useState({
    EmpCode: '',
    FullName: '',
    Department: '',
    LineUserID: '',
    IsActive: true,
    department_id: ''
  });

  useEffect(() => {
    fetchEmployees();
    fetchDepartments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- API Handlers (Axios) ---
  const fetchEmployees = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE_URL}/E_employees?department_id=${user?.department_id}`, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setEmployees(res.data);
    } catch (err) {
      console.error("Fetch employees error:", err);
      alert("ไม่สามารถโหลดข้อมูลพนักงานได้");
    } finally {
      setLoading(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/show_departments`, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setDepartments(res.data);
    } catch (err) {
      console.error("Fetch departments error:", err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (name === 'department_id') {
      const selectedDept = departments.find(d => d.id.toString() === value.toString());
      setFormData(prev => ({
        ...prev,
        department_id: value,
        Department: selectedDept ? selectedDept.name : ''
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: type === 'checkbox' ? checked : value
      }));
    }
  };

  const resetForm = () => {
    setFormData({
      EmpCode: '',
      FullName: '',
      Department: '',
      LineUserID: '',
      IsActive: true,
      department_id: user?.department_id || ''
    });
  };

  const openAddModal = () => {
    resetForm();
    setShowAddModal(true);
  };

  const openEditModal = (emp) => {
    setSelectedEmp(emp);
    setFormData({
      EmpCode: emp.EmpCode,
      FullName: emp.FullName || '',
      Department: emp.Department || '',
      LineUserID: emp.LineUserID || '',
      IsActive: emp.IsActive === true || emp.IsActive === 1,
      department_id: emp.department_id || '',
      DefaultOffDay: emp.DefaultOffDay !== null && emp.DefaultOffDay !== undefined ? emp.DefaultOffDay : '',
      DefaultWfhDay: emp.DefaultWfhDay !== null && emp.DefaultWfhDay !== undefined ? emp.DefaultWfhDay : ''
    });
    setShowEditModal(true);
  };

  const openDeleteModal = (emp) => {
    setSelectedEmp(emp);
    setShowDeleteModal(true);
  };

  const handleAddSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${API_BASE_URL}/E_employees_A`, formData, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setShowAddModal(false);
      resetForm();
      fetchEmployees();
    } catch (err) {
      console.error("Add employee error:", err);
      alert("เกิดข้อผิดพลาดในการเพิ่มพนักงาน");
    }
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`${API_BASE_URL}/E_employees/${formData.EmpCode}`, formData, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });

      // อัปเดตวันหยุด/WFH ล็อกประจำสัปดาห์
      await axios.post(`${API_BASE_URL}/employees/set-default-shifts`, {
        empCode: formData.EmpCode,
        defaultOffDay: formData.DefaultOffDay !== '' ? formData.DefaultOffDay : null,
        defaultWfhDay: formData.DefaultWfhDay !== '' ? formData.DefaultWfhDay : null
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });

      setShowEditModal(false);
      resetForm();
      fetchEmployees();
    } catch (err) {
      console.error("Edit employee error:", err);
      alert("เกิดข้อผิดพลาดในการแก้ไขข้อมูล");
    }
  };

  const handleDeleteSubmit = async () => {
    if (!selectedEmp) return;
    try {
      await axios.delete(`${API_BASE_URL}/E_employees/${selectedEmp.EmpCode}`, { headers: { 'ngrok-skip-browser-warning': '69420' } });
      setShowDeleteModal(false);
      setSelectedEmp(null);
      fetchEmployees();
    } catch (err) {
      console.error("Delete employee error:", err);
      alert("เกิดข้อผิดพลาดในการลบพนักงาน");
    }
  };

  const handleToggleLineNotify = async (empCode, newStatus) => {
    try {
      await axios.post(`${API_BASE_URL}/employees/toggle-line-notify`, {
        empCode,
        isEnabled: newStatus
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setEmployees(prev => prev.map(emp => {
        if (emp.EmpCode === empCode) {
          return { ...emp, IsLineNotifyEnabled: newStatus };
        }
        return emp;
      }));
    } catch (err) {
      console.error("Toggle line notify error:", err);
      alert("เกิดข้อผิดพลาดในการปรับสถานะการแจ้งเตือน LINE");
    }
  };

  const handleToggleLocked9Am = async (empCode, newStatus) => {
    try {
      await axios.post(`${API_BASE_URL}/employees/set-locked-9am`, {
        empCode,
        isLocked: newStatus
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setEmployees(prev => prev.map(emp => {
        if (emp.EmpCode === empCode) {
          return { ...emp, IsLocked9Am: newStatus };
        }
        return emp;
      }));
    } catch (err) {
      console.error("Toggle locked 9am error:", err);
      alert("เกิดข้อผิดพลาดในการเปลี่ยนสถานะล็อกกะ 9 โมง");
    }
  };

  // กรองค้นหาพนักงานในหน้า Client
  const filteredEmployees = employees.filter(emp => {
    const term = searchTerm.toLowerCase();
    const code = (emp.EmpCode || '').toLowerCase();
    const name = (emp.FullName || '').toLowerCase();
    const dept = (emp.department_name || emp.Department || '').toLowerCase();
    return code.includes(term) || name.includes(term) || dept.includes(term);
  });

  return (
    <div className="main-viewport">
      {/* Top Header Card */}
      <div className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200/80 shadow-sm mb-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                <Users className="w-4 h-4" />
              </span>
              <h1 className="text-xl sm:text-2xl font-bold text-slate-900 tracking-tight">
                Employee Management
              </h1>
            </div>
            <p className="text-xs sm:text-sm text-slate-500 mt-1 pl-10">
              จัดการข้อมูลพนักงานในระบบ (จำนวนทั้งหมด: {employees.length} คน)
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2.5">
            {/* Search Input */}
            <div className="relative">
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              <input
                type="text"
                placeholder="ค้นหารหัส หรือชื่อพนักงาน..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-3.5 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 w-52 sm:w-64"
              />
            </div>

            {/* Add Employee Button */}
            <button 
              onClick={openAddModal}
              className="inline-flex items-center gap-1.5 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm transition-all"
            >
              <UserPlus className="w-4 h-4" />
              <span>เพิ่มพนักงานใหม่</span>
            </button>
          </div>
        </div>
      </div>

      {/* Main Table Card */}
      <div className="bg-white rounded-2xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs sm:text-sm">
            <thead>
              <tr className="bg-slate-50 text-slate-600 border-b border-slate-200">
                <th className="py-3 px-4 font-bold">รหัสพนักงาน</th>
                <th className="py-3 px-4 font-bold">ชื่อ - นามสกุล</th>
                <th className="py-3 px-4 font-bold">แผนก (Department)</th>
                <th className="py-3 px-4 font-bold text-center">สถานะ</th>
                <th className="py-3 px-4 font-bold text-center">แจ้งเตือน LINE</th>
                <th className="py-3 px-4 font-bold text-center">ประจำกะ 9 โมง (F13)</th>
                <th className="py-3 px-4 font-bold text-center">การจัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="7" className="py-12 text-center text-slate-400">
                    กำลังโหลดข้อมูลพนักงาน...
                  </td>
                </tr>
              ) : filteredEmployees.length === 0 ? (
                <tr>
                  <td colSpan="7" className="py-12 text-center">
                    <div className="flex flex-col items-center justify-center py-6 text-slate-400">
                      <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400 mb-2">
                        <Search className="w-6 h-6" />
                      </div>
                      <p className="font-semibold text-slate-700 text-sm">ไม่พบข้อมูลพนักงานที่ตรงกับเงื่อนไข</p>
                      <p className="text-xs text-slate-400 mt-0.5">ลองค้นหาด้วยรหัส หรือชื่อ-นามสกุลอื่น</p>
                      {searchTerm && (
                        <button
                          type="button"
                          onClick={() => setSearchTerm('')}
                          className="mt-3 px-3 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-600 rounded-lg text-xs font-semibold transition-colors cursor-pointer"
                        >
                          ล้างคำค้นหา
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ) : (
                filteredEmployees.map((emp) => (
                  <tr key={emp.EmpCode} className="hover:bg-slate-50/70 transition-colors">
                    <td className="py-3 px-4 font-semibold text-slate-800">
                      <span className="font-mono text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-700 font-bold">{emp.EmpCode}</span>
                    </td>
                    <td className="py-3 px-4 font-medium text-slate-800">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-xl overflow-hidden bg-indigo-50 border border-indigo-100/80 flex items-center justify-center text-xs font-bold text-indigo-600 shrink-0 shadow-xs">
                          {emp.ProfileImage ? (
                            <img src={emp.ProfileImage} alt={emp.FullName} className="w-full h-full object-cover" />
                          ) : (
                            emp.FullName ? emp.FullName[0].toUpperCase() : 'E'
                          )}
                        </div>
                        <div>
                          <div className="font-semibold text-slate-900">{emp.FullName}</div>
                          {((emp.DefaultOffDay !== null && emp.DefaultOffDay !== undefined) || (emp.DefaultWfhDay !== null && emp.DefaultWfhDay !== undefined)) && (
                            <div className="flex items-center gap-1.5 mt-0.5 text-[10px]">
                              {emp.DefaultOffDay !== null && emp.DefaultOffDay !== undefined && (
                                <span className="px-1.5 py-0.2 rounded bg-rose-50 text-rose-700 border border-rose-200 font-semibold">
                                  หยุด: {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'][emp.DefaultOffDay]}
                                </span>
                              )}
                              {emp.DefaultWfhDay !== null && emp.DefaultWfhDay !== undefined && (
                                <span className="px-1.5 py-0.2 rounded bg-sky-50 text-sky-700 border border-sky-200 font-semibold">
                                  WFH: {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'][emp.DefaultWfhDay]}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="py-3 px-4 text-slate-600">
                      {emp.department_name || emp.Department || '-'}
                    </td>
                    <td className="py-3 px-4 text-center">
                      <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold ${
                        emp.IsActive
                          ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' 
                          : 'bg-rose-50 text-rose-700 border border-rose-200'
                      }`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${emp.IsActive ? 'bg-emerald-500' : 'bg-rose-500'}`}></span>
                        {emp.IsActive ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <button
                        type="button"
                        onClick={() => handleToggleLineNotify(emp.EmpCode, !(emp.IsLineNotifyEnabled !== false && emp.IsLineNotifyEnabled !== 0))}
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all shadow-xs ${
                          emp.IsLineNotifyEnabled !== false && emp.IsLineNotifyEnabled !== 0
                            ? 'bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100'
                            : 'bg-slate-100 text-slate-500 border border-slate-200 hover:bg-slate-200'
                        }`}
                        title="คลิกเพื่อ เปิด/ปิด การแจ้งเตือน LINE อัตโนมัติให้พนักงานคนนี้"
                      >
                        {emp.IsLineNotifyEnabled !== false && emp.IsLineNotifyEnabled !== 0 ? (
                          <>
                            <Bell className="w-3.5 h-3.5 text-emerald-600" />
                            <span>เปิดแจ้งเตือน</span>
                          </>
                        ) : (
                          <>
                            <BellOff className="w-3.5 h-3.5 text-slate-400" />
                            <span>ปิดแจ้งเตือน</span>
                          </>
                        )}
                      </button>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <button
                        type="button"
                        onClick={() => handleToggleLocked9Am(emp.EmpCode, !(emp.IsLocked9Am === 1 || emp.IsLocked9Am === true))}
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold transition-all shadow-xs ${
                          emp.IsLocked9Am === 1 || emp.IsLocked9Am === true
                            ? 'bg-teal-50 text-teal-700 border border-teal-200 hover:bg-teal-100'
                            : 'bg-slate-100 text-slate-400 border border-slate-200 hover:bg-slate-200'
                        }`}
                        title="คลิกเพื่อ ล็อก/ปลดล็อก พนักงานประจำกะ 9:00 น. (F13)"
                      >
                        <Clock className="w-3.5 h-3.5" />
                        <span>{emp.IsLocked9Am === 1 || emp.IsLocked9Am === true ? 'ล็อก 9 โมง' : 'กะปกติ'}</span>
                      </button>
                    </td>
                    <td className="py-3 px-4 text-center">
                      <div className="flex items-center justify-center gap-1.5">
                        <button 
                          onClick={() => openEditModal(emp)}
                          className="p-1.5 rounded-lg text-amber-700 hover:bg-amber-50 transition-colors"
                          title="แก้ไขข้อมูล"
                        >
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => openDeleteModal(emp)}
                          className="p-1.5 rounded-lg text-rose-600 hover:bg-rose-50 transition-colors"
                          title="ลบพนักงาน"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* ========================================== */}
      {/* 1. Modal: เพิ่มพนักงาน (Add Modal) */}
      {/* ========================================== */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100">
              <h2 className="font-bold text-slate-900 text-base flex items-center gap-2">
                <UserPlus className="w-4 h-4 text-indigo-600" /> เพิ่มพนักงานใหม่
              </h2>
              <button 
                onClick={() => setShowAddModal(false)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAddSubmit} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  รหัสพนักงาน (EmpCode) *
                </label>
                <input 
                  type="text" 
                  name="EmpCode" 
                  value={formData.EmpCode} 
                  onChange={handleInputChange} 
                  required 
                  placeholder="เช่น 0076640" 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ชื่อ-นามสกุล *
                </label>
                <input 
                  type="text" 
                  name="FullName" 
                  value={formData.FullName} 
                  onChange={handleInputChange} 
                  required 
                  placeholder="เช่น นายสมชาย สายชล" 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  แผนก (Department) *
                </label>
                <select
                  name="department_id" 
                  value={formData.department_id} 
                  onChange={handleInputChange}
                  required
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="">-- กรุณาเลือกแผนก --</option>
                  {departments.map((dept) => (
                    <option key={dept.id} value={dept.id}>
                      {dept.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="flex justify-end gap-2 pt-3">
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
                >
                  ยกเลิก
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
                >
                  บันทึกข้อมูล
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================== */}
      {/* 2. Modal: แก้ไขพนักงาน (Edit Modal) */}
      {/* ========================================== */}
      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100">
              <h2 className="font-bold text-slate-900 text-base flex items-center gap-2">
                <Pencil className="w-4 h-4 text-amber-600" /> แก้ไขข้อมูลพนักงาน
              </h2>
              <button 
                onClick={() => setShowEditModal(false)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleEditSubmit} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  รหัสพนักงาน (EmpCode)
                </label>
                <input 
                  type="text" 
                  name="EmpCode" 
                  value={formData.EmpCode} 
                  disabled 
                  className="w-full px-3 py-2 bg-slate-100 border border-slate-200 rounded-xl text-sm text-slate-500 font-semibold cursor-not-allowed"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ชื่อ-นามสกุล *
                </label>
                <input 
                  type="text" 
                  name="FullName" 
                  value={formData.FullName} 
                  onChange={handleInputChange} 
                  required 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  แผนก (Department) *
                </label>
                <select
                  name="department_id" 
                  value={formData.department_id} 
                  onChange={handleInputChange}
                  required
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="">-- กรุณาเลือกแผนก --</option>
                  {departments.map((dept) => (
                    <option key={dept.id} value={dept.id}>
                      {dept.name}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  Line User ID
                </label>
                <input 
                  type="text" 
                  name="LineUserID" 
                  value={formData.LineUserID} 
                  onChange={handleInputChange} 
                  placeholder="เช่น U123456789..."
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div className="grid grid-cols-2 gap-3 pt-1">
                <div>
                  <label className="block text-xs font-semibold text-rose-700 mb-1">
                    วันหยุดประจำสัปดาห์ (OFF)
                  </label>
                  <select
                    name="DefaultOffDay"
                    value={formData.DefaultOffDay !== null && formData.DefaultOffDay !== undefined ? formData.DefaultOffDay : ''}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-rose-500 cursor-pointer"
                  >
                    <option value="">-- ไม่ล็อก (อัตโนมัติ) --</option>
                    <option value="0">วันอาทิตย์</option>
                    <option value="1">วันจันทร์</option>
                    <option value="2">วันอังคาร</option>
                    <option value="3">วันพุธ</option>
                    <option value="4">วันพฤหัสบดี</option>
                    <option value="5">วันศุกร์</option>
                    <option value="6">วันเสาร์</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-semibold text-sky-700 mb-1">
                    วัน WFH ประจำสัปดาห์ (ZE02)
                  </label>
                  <select
                    name="DefaultWfhDay"
                    value={formData.DefaultWfhDay !== null && formData.DefaultWfhDay !== undefined ? formData.DefaultWfhDay : ''}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-sky-500 cursor-pointer"
                  >
                    <option value="">-- ไม่ล็อก (อัตโนมัติ) --</option>
                    <option value="0">วันอาทิตย์</option>
                    <option value="1">วันจันทร์</option>
                    <option value="2">วันอังคาร</option>
                    <option value="3">วันพุธ</option>
                    <option value="4">วันพฤหัสบดี</option>
                    <option value="5">วันศุกร์</option>
                    <option value="6">วันเสาร์</option>
                  </select>
                </div>
              </div>

              <div className="flex items-center gap-2 pt-1">
                <input 
                  type="checkbox" 
                  id="IsActiveEdit" 
                  name="IsActive" 
                  checked={formData.IsActive} 
                  onChange={handleInputChange} 
                  className="w-4 h-4 text-indigo-600 rounded cursor-pointer"
                />
                <label htmlFor="IsActiveEdit" className="text-xs font-semibold text-slate-700 cursor-pointer">
                  เปิดใช้งานบัญชี (Active Status)
                </label>
              </div>

              <div className="flex justify-end gap-2 pt-3">
                <button
                  type="button"
                  onClick={() => setShowEditModal(false)}
                  className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
                >
                  ยกเลิก
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-amber-500 hover:bg-amber-600 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
                >
                  อัปเดตข้อมูล
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================== */}
      {/* 3. Modal: ยืนยันการลบ (Delete Modal) */}
      {/* ========================================== */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center font-bold flex-shrink-0">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <h2 className="font-bold text-slate-900 text-base">ยืนยันการลบพนักงาน</h2>
                <p className="text-xs text-slate-500">การกระทำนี้ไม่สามารถย้อนกลับได้</p>
              </div>
            </div>

            <p className="text-xs sm:text-sm text-slate-600 bg-slate-50 p-3 rounded-xl border border-slate-200">
              คุณต้องการลบพนักงานรหัส <b>{selectedEmp?.EmpCode}</b> ({selectedEmp?.FullName}) ออกจากระบบใช่หรือไม่?
            </p>

            <div className="flex justify-end gap-2 pt-2">
              <button
                type="button"
                onClick={() => setShowDeleteModal(false)}
                className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
              >
                ยกเลิก
              </button>
              <button
                type="button"
                onClick={handleDeleteSubmit}
                className="px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
              >
                ยืนยันลบ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
