import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Myhostlocalapi } from './../Myhostlocalapi';
import { 
  UserCheck, 
  UserPlus, 
  Search, 
  Shield, 
  Eye, 
  EyeOff, 
  X,
  Pencil,
  Trash2,
  AlertTriangle
} from 'lucide-react';

const API_BASE_URL = `${Myhostlocalapi}/api`;

export default function UserManagement() {
  const currentUser = JSON.parse(localStorage.getItem('user')) || null;
  const [users, setUsers] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [visiblePasswords, setVisiblePasswords] = useState({});

  // Modals state
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);

  // Form states
  const [formData, setFormData] = useState({
    Username: '',
    Password: '',
    Role: 'User',
    EmployeeID: ''
  });

  const [editFormData, setEditFormData] = useState({
    Username: '',
    Password: '',
    Role: 'User',
    EmployeeID: ''
  });
  const [showEditPassword, setShowEditPassword] = useState(false);

  useEffect(() => {
    fetchUsers();
    fetchEmployees();
  }, []);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE_URL}/users`, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setUsers(res.data);
    } catch (err) {
      console.error("Fetch users error:", err);
    } finally {
      setLoading(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      // ดึงรายชื่อพนักงานทั้งหมด เพื่อให้ Dropdown แสดงได้ครบถ้วน
      const res = await axios.get(`${API_BASE_URL}/employees`, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setEmployees(res.data);
    } catch (err) {
      console.error("Fetch employees error:", err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleEditInputChange = (e) => {
    const { name, value } = e.target;
    setEditFormData(prev => ({ ...prev, [name]: value }));
  };

  // --- Add User ---
  const handleAddSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${API_BASE_URL}/users`, formData, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setShowAddModal(false);
      setFormData({ Username: '', Password: '', Role: 'User', EmployeeID: '' });
      fetchUsers();
    } catch (err) {
      console.error("Add user error:", err);
      alert(err.response?.data?.error || "เกิดข้อผิดพลาดในการเพิ่มผู้ใช้งาน");
    }
  };

  // --- Edit User ---
  const openEditModal = (u) => {
    setSelectedUser(u);
    setEditFormData({
      Username: u.Username || '',
      Password: '', // ปล่อยว่างไว้ หากไม่เปลี่ยนรหัสผ่าน
      Role: u.Role || 'User',
      EmployeeID: u.EmployeeID || ''
    });
    setShowEditPassword(false);
    setShowEditModal(true);
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    if (!selectedUser) return;
    try {
      await axios.put(`${API_BASE_URL}/users/${selectedUser.UserID}`, editFormData, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setShowEditModal(false);
      setSelectedUser(null);
      fetchUsers();
    } catch (err) {
      console.error("Update user error:", err);
      alert(err.response?.data?.error || "เกิดข้อผิดพลาดในการแก้ไขข้อมูลผู้ใช้งาน");
    }
  };

  // --- Delete User ---
  const openDeleteModal = (u) => {
    setSelectedUser(u);
    setShowDeleteModal(true);
  };

  const handleDeleteSubmit = async () => {
    if (!selectedUser) return;
    try {
      await axios.delete(`${API_BASE_URL}/users/${selectedUser.UserID}`, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setShowDeleteModal(false);
      setSelectedUser(null);
      fetchUsers();
    } catch (err) {
      console.error("Delete user error:", err);
      alert(err.response?.data?.error || "เกิดข้อผิดพลาดในการลบผู้ใช้งาน");
    }
  };

  const togglePasswordVisibility = (userId) => {
    setVisiblePasswords(prev => ({
      ...prev,
      [userId]: !prev[userId]
    }));
  };

  const filteredUsers = users.filter(u => {
    const term = searchTerm.toLowerCase();
    const uname = (u.Username || '').toLowerCase();
    const empName = (u.EmployeeName || '').toLowerCase();
    const role = (u.Role || '').toLowerCase();
    return uname.includes(term) || empName.includes(term) || role.includes(term);
  });

  return (
    <div className="main-viewport">
      {/* Top Header Card */}
      <div className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200/80 shadow-sm mb-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                <UserCheck className="w-4 h-4" />
              </span>
              <h1 className="text-xl sm:text-2xl font-bold text-slate-900 tracking-tight">
                User Management
              </h1>
            </div>
            <p className="text-xs sm:text-sm text-slate-500 mt-1 pl-10">
              จัดการบัญชีผู้ใช้งานระบบ ShiftPro (ผู้ใช้งานทั้งหมด: {users.length} บัญชี)
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2.5">
            {/* Search Input */}
            <div className="relative">
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              <input
                type="text"
                placeholder="ค้นหาชื่อผู้ใช้ หรือพนักงาน..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-3.5 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 w-52 sm:w-64"
              />
            </div>

            {/* Add User Button */}
            <button 
              onClick={() => {
                setFormData({ Username: '', Password: '', Role: 'User', EmployeeID: '' });
                setShowAddModal(true);
              }}
              className="inline-flex items-center gap-1.5 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm transition-all"
            >
              <UserPlus className="w-4 h-4" />
              <span>เพิ่มผู้ใช้งานใหม่</span>
            </button>
          </div>
        </div>
      </div>

      {/* Users Table Card */}
      <div className="bg-white rounded-2xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs sm:text-sm">
            <thead>
              <tr className="bg-slate-50 text-slate-600 border-b border-slate-200">
                <th className="py-3 px-4 font-bold">User ID</th>
                <th className="py-3 px-4 font-bold">ชื่อผู้ใช้ (Username)</th>
                <th className="py-3 px-4 font-bold">รหัสผ่าน</th>
                <th className="py-3 px-4 font-bold">ระดับสิทธิ์ (Role)</th>
                <th className="py-3 px-4 font-bold">พนักงานที่ผูก (Employee)</th>
                <th className="py-3 px-4 font-bold text-slate-500">วันที่สร้าง</th>
                <th className="py-3 px-4 font-bold text-center">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan="7" className="py-12 text-center text-slate-400">
                    กำลังโหลดข้อมูลผู้ใช้งาน...
                  </td>
                </tr>
              ) : filteredUsers.length === 0 ? (
                <tr>
                  <td colSpan="7" className="py-12 text-center text-slate-400">
                    ไม่พบข้อมูลผู้ใช้งานที่ค้นหา
                  </td>
                </tr>
              ) : (
                filteredUsers.map((u) => {
                  const isPassVisible = !!visiblePasswords[u.UserID];
                  return (
                    <tr key={u.UserID} className="hover:bg-slate-50/70 transition-colors">
                      <td className="py-3 px-4 font-semibold text-slate-500">
                        #{u.UserID}
                      </td>
                      <td className="py-3 px-4 font-bold text-slate-800">
                        <div className="flex items-center gap-2.5">
                          <div className="w-7 h-7 rounded-lg overflow-hidden bg-indigo-50 border border-indigo-100/80 flex items-center justify-center text-xs font-bold text-indigo-600 shrink-0">
                            {u.ProfileImage ? (
                              <img src={u.ProfileImage} alt={u.Username} className="w-full h-full object-cover" />
                            ) : (
                              u.Username ? u.Username[0].toUpperCase() : 'U'
                            )}
                          </div>
                          <span>{u.Username}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4 text-slate-600">
                        <div className="inline-flex items-center gap-2 bg-slate-50 px-2 py-1 rounded-lg border border-slate-200 font-mono text-xs">
                          <span>{isPassVisible ? u.Password : '••••••••'}</span>
                          <button
                            type="button"
                            onClick={() => togglePasswordVisibility(u.UserID)}
                            className="text-slate-400 hover:text-slate-600 focus:outline-none"
                            title={isPassVisible ? "ซ่อนรหัสผ่าน" : "แสดงรหัสผ่าน"}
                          >
                            {isPassVisible ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                          </button>
                        </div>
                      </td>
                      <td className="py-3 px-4">
                        <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold ${
                          u.Role?.toLowerCase() === 'admin'
                            ? 'bg-amber-50 text-amber-700 border border-amber-200'
                            : u.Role?.toLowerCase() === 'manager'
                            ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                            : 'bg-indigo-50 text-indigo-700 border border-indigo-200'
                        }`}>
                          <Shield className="w-3 h-3" />
                          {u.Role}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-slate-700 font-medium">
                        {u.EmployeeName ? (
                          <div className="flex items-center gap-1.5">
                            <span className="w-6 h-6 rounded-md bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-600">
                              {u.EmployeeName[0]}
                            </span>
                            <span>{u.EmployeeName} ({u.EmployeeID})</span>
                          </div>
                        ) : (
                          <span className="text-slate-400">-</span>
                        )}
                      </td>
                      <td className="py-3 px-4 text-slate-500 text-xs">
                        {u.CreatedAt ? new Date(u.CreatedAt).toLocaleString('th-TH') : '-'}
                      </td>
                      <td className="py-3 px-4 text-center">
                        <div className="flex items-center justify-center gap-1.5">
                          <button 
                            type="button"
                            onClick={() => openEditModal(u)}
                            className="p-1.5 rounded-lg text-amber-700 hover:bg-amber-50 transition-colors"
                            title="แก้ไขข้อมูลผู้ใช้"
                          >
                            <Pencil className="w-4 h-4" />
                          </button>
                          <button 
                            type="button"
                            onClick={() => openDeleteModal(u)}
                            className="p-1.5 rounded-lg text-rose-600 hover:bg-rose-50 transition-colors"
                            title="ลบผู้ใช้งาน"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* ========================================== */}
      {/* 1. Modal: เพิ่มผู้ใช้งานใหม่ (Add User Modal) */}
      {/* ========================================== */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100">
              <h2 className="font-bold text-slate-900 text-base flex items-center gap-2">
                <UserPlus className="w-4 h-4 text-indigo-600" /> เพิ่มผู้ใช้งานใหม่
              </h2>
              <button 
                onClick={() => setShowAddModal(false)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleAddSubmit} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ชื่อผู้ใช้ (Username) *
                </label>
                <input 
                  type="text" 
                  name="Username" 
                  value={formData.Username} 
                  onChange={handleInputChange} 
                  required 
                  placeholder="เช่น it_admin" 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  รหัสผ่าน (Password) *
                </label>
                <input 
                  type="text" 
                  name="Password" 
                  value={formData.Password} 
                  onChange={handleInputChange} 
                  required 
                  placeholder="กรอกรหัสผ่าน" 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ระดับสิทธิ์ (Role) *
                </label>
                <select 
                  name="Role" 
                  value={formData.Role} 
                  onChange={handleInputChange} 
                  required 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="User">User</option>
                  <option value="Admin">Admin</option>
                  <option value="Manager">Manager</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  พนักงานที่ผูก (Employee ID)
                </label>
                <select 
                  name="EmployeeID" 
                  value={formData.EmployeeID} 
                  onChange={handleInputChange} 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="">-- ไม่ระบุ (ไม่มีการผูกพนักงาน) --</option>
                  {employees.map((emp) => {
                    const isBound = users.some(u => u.EmployeeID === emp.EmpCode);
                    return (
                      <option 
                        key={emp.EmpCode} 
                        value={emp.EmpCode}
                        disabled={isBound}
                      >
                        {emp.FullName} ({emp.EmpCode}) {isBound ? ' [ผูกกับผู้ใช้อื่นแล้ว]' : ''}
                      </option>
                    );
                  })}
                </select>
              </div>

              <div className="flex justify-end gap-2 pt-3">
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
                >
                  ยกเลิก
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
                >
                  บันทึกผู้ใช้
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================== */}
      {/* 2. Modal: แก้ไขข้อมูลผู้ใช้ (Edit User Modal) */}
      {/* ========================================== */}
      {showEditModal && selectedUser && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex justify-between items-center pb-3 border-b border-slate-100">
              <h2 className="font-bold text-slate-900 text-base flex items-center gap-2">
                <Pencil className="w-4 h-4 text-amber-600" /> แก้ไขข้อมูลผู้ใช้งาน (#{selectedUser.UserID})
              </h2>
              <button 
                onClick={() => setShowEditModal(false)}
                className="p-1 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleEditSubmit} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ชื่อผู้ใช้ (Username) *
                </label>
                <input 
                  type="text" 
                  name="Username" 
                  value={editFormData.Username} 
                  onChange={handleEditInputChange} 
                  required 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  รหัสผ่านใหม่ (Password)
                </label>
                <div className="relative">
                  <input 
                    type={showEditPassword ? "text" : "password"} 
                    name="Password" 
                    value={editFormData.Password} 
                    onChange={handleEditInputChange} 
                    placeholder="เว้นว่างไว้หากไม่ต้องการเปลี่ยนรหัสผ่านเดิม" 
                    className="w-full pl-3 pr-10 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  />
                  <button
                    type="button"
                    onClick={() => setShowEditPassword(!showEditPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 focus:outline-none"
                    title={showEditPassword ? "ซ่อนรหัสผ่าน" : "แสดงรหัสผ่าน"}
                  >
                    {showEditPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
                <p className="text-[11px] text-slate-400 mt-1">
                  * หากต้องการใช้รหัสผ่านเดิม ไม่ต้องกรอกช่องนี้
                </p>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  ระดับสิทธิ์ (Role) *
                </label>
                <select 
                  name="Role" 
                  value={editFormData.Role} 
                  onChange={handleEditInputChange} 
                  required 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="User">User</option>
                  <option value="Admin">Admin</option>
                  <option value="Manager">Manager</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">
                  พนักงานที่ผูก (Employee ID)
                </label>
                <select 
                  name="EmployeeID" 
                  value={editFormData.EmployeeID} 
                  onChange={handleEditInputChange} 
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
                >
                  <option value="">-- ไม่ระบุ (ไม่มีการผูกพนักงาน) --</option>
                  {employees.map((emp) => {
                    const isBoundToOther = users.some(u => u.EmployeeID === emp.EmpCode && u.UserID !== selectedUser.UserID);
                    return (
                      <option 
                        key={emp.EmpCode} 
                        value={emp.EmpCode}
                        disabled={isBoundToOther}
                      >
                        {emp.FullName} ({emp.EmpCode}) {isBoundToOther ? ' [ผูกกับผู้ใช้อื่นแล้ว]' : ''}
                      </option>
                    );
                  })}
                </select>
              </div>

              <div className="flex justify-end gap-2 pt-3">
                <button
                  type="button"
                  onClick={() => setShowEditModal(false)}
                  className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
                >
                  ยกเลิก
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-amber-600 hover:bg-amber-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
                >
                  บันทึกการแก้ไข
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ========================================== */}
      {/* 3. Modal: ยืนยันการลบ (Delete User Modal) */}
      {/* ========================================== */}
      {showDeleteModal && selectedUser && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-sm p-6 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-rose-50 text-rose-600 flex items-center justify-center font-bold flex-shrink-0">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <div>
                <h2 className="font-bold text-slate-900 text-base">ยืนยันการลบผู้ใช้งาน</h2>
                <p className="text-xs text-slate-500">การกระทำนี้ไม่สามารถย้อนกลับได้</p>
              </div>
            </div>

            <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200 text-xs sm:text-sm text-slate-600 space-y-1.5">
              <p>
                คุณต้องการลบผู้ใช้งาน <b className="text-slate-900 font-bold">{selectedUser.Username}</b> (#{selectedUser.UserID}) ออกจากระบบใช่หรือไม่?
              </p>
              {selectedUser.EmployeeName && (
                <p className="text-slate-500 text-xs">
                  พนักงานที่ผูก: <span className="font-medium text-slate-700">{selectedUser.EmployeeName} ({selectedUser.EmployeeID})</span>
                </p>
              )}
              {currentUser?.UserID === selectedUser.UserID && (
                <div className="p-2 mt-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-xs font-semibold flex items-center gap-1.5">
                  <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
                  <span>คำเตือน: คุณกำลังเลือกลบบัญชีที่คุณกำลังล็อกอินใช้งานอยู่!</span>
                </div>
              )}
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <button
                type="button"
                onClick={() => setShowDeleteModal(false)}
                className="px-4 py-2 border border-slate-200 text-slate-700 rounded-xl text-xs sm:text-sm font-semibold hover:bg-slate-100"
              >
                ยกเลิก
              </button>
              <button
                type="button"
                onClick={handleDeleteSubmit}
                className="px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm"
              >
                ยืนยันลบ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
