import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Myhostlocalapi } from './../Myhostlocalapi';
import { 
  User, 
  ShieldCheck, 
  Briefcase, 
  Hash, 
  Building, 
  CheckCircle2, 
  Bell, 
  BellOff,
  Camera,
  Trash2,
  Upload,
  Loader2,
  Calendar,
  Coffee,
  Home,
  Clock
} from 'lucide-react';

export default function ProfileView({ user, setUser }) {
  const currentUser = user || JSON.parse(localStorage.getItem('user')) || {};
  const [isLineNotifyEnabled, setIsLineNotifyEnabled] = useState(true);
  const [notifyTime, setNotifyTime] = useState('20:00');
  const [notifyDaysBefore, setNotifyDaysBefore] = useState(1);
  const [isUpdatingNotify, setIsUpdatingNotify] = useState(false);
  const [isTestingNotify, setIsTestingNotify] = useState(false);
  const [notifyFeedback, setNotifyFeedback] = useState(null);
  const [profileImage, setProfileImage] = useState(currentUser.profileImage || null);
  const [empDetails, setEmpDetails] = useState(null);
  const [isUploadingImage, setIsUploadingImage] = useState(false);
  const fileInputRef = useRef(null);

  const empCode = currentUser.empCode || currentUser.EmpCode;

  // ดึงข้อมูลการตั้งค่ากะของพนักงาน
  useEffect(() => {
    if (!empCode) return;
    const fetchEmp = async () => {
      try {
        const res = await axios.get(`${Myhostlocalapi}/api/employees?department_id=${currentUser.department_id || ''}`, {
          headers: { 'ngrok-skip-browser-warning': '69420' }
        });
        const found = res.data.find(e => (e.EmpCode || e.empCode) === empCode);
        if (found) setEmpDetails(found);
      } catch (err) {
        console.error("Fetch emp details error:", err);
      }
    };
    fetchEmp();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [empCode]);

  // ดึงสถานะและการตั้งค่าการแจ้งเตือน LINE
  useEffect(() => {
    if (!empCode) return;
    const fetchStatus = async () => {
      try {
        const res = await axios.get(`${Myhostlocalapi}/api/employees/notify-settings?empCode=${empCode}`, {
          headers: { 'ngrok-skip-browser-warning': '69420' }
        });
        if (res.data) {
          setIsLineNotifyEnabled(!!res.data.isLineNotifyEnabled);
          setNotifyTime(res.data.notifyTime || '20:00');
          setNotifyDaysBefore(res.data.notifyDaysBefore !== undefined ? res.data.notifyDaysBefore : 1);
        }
      } catch (err) {
        console.error("Error fetching LINE notify status:", err);
      }
    };
    fetchStatus();
  }, [empCode]);

  // ดึงรูปโปรไฟล์ล่าสุดจาก Database
  useEffect(() => {
    const fetchProfileImg = async () => {
      try {
        const res = await axios.get(
          `${Myhostlocalapi}/api/users/profile-image?username=${currentUser.username || ''}&empCode=${empCode || ''}`,
          { headers: { 'ngrok-skip-browser-warning': '69420' } }
        );
        if (res.data?.profileImage) {
          setProfileImage(res.data.profileImage);
          const updated = { ...currentUser, profileImage: res.data.profileImage };
          localStorage.setItem('user', JSON.stringify(updated));
          if (setUser) setUser(updated);
        }
      } catch (err) {
        console.error("Error fetching profile image:", err);
      }
    };
    fetchProfileImg();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUser.username, empCode]);

  // อัปโหลดและบันทึกรูปโปรไฟล์
  const handleImageUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      alert('กรุณาเลือกไฟล์รูปภาพเท่านั้น (JPG, PNG, WebP ฯลฯ)');
      return;
    }

    setIsUploadingImage(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        // ปรับขนาดรูปภาพให้อัตโนมัติ (Max 500x500px) เพื่อให้ภาพคมชัดและขนาดกะทัดรัด
        const canvas = document.createElement('canvas');
        const maxDim = 500;
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxDim) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          }
        } else {
          if (height > maxDim) {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        const resizedBase64 = canvas.toDataURL('image/jpeg', 0.88);

        saveProfileImage(resizedBase64);
      };
      img.src = event.target.result;
    };
    reader.readAsDataURL(file);
    // Reset file input value
    e.target.value = '';
  };

  const saveProfileImage = async (base64) => {
    try {
      await axios.post(`${Myhostlocalapi}/api/users/profile-image`, {
        userId: currentUser.userId || currentUser.UserID,
        empCode: empCode,
        username: currentUser.username,
        profileImage: base64
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });

      setProfileImage(base64);

      // อัปเดต localStorage และ state รวม
      const updatedUser = { ...currentUser, profileImage: base64 };
      localStorage.setItem('user', JSON.stringify(updatedUser));
      if (setUser) setUser(updatedUser);
      window.dispatchEvent(new Event('user-profile-updated'));

      alert("อัปเดตรูปส่วนตัวลงในหน้าปกเรียบร้อยแล้ว!");
    } catch (err) {
      console.error("Save profile image error:", err);
      alert("เกิดข้อผิดพลาดในการบันทึกรูปโปรไฟล์: " + (err.response?.data?.error || err.message));
    } finally {
      setIsUploadingImage(false);
    }
  };

  const handleRemoveImage = async () => {
    if (!window.confirm("คุณต้องการลบรูปส่วนตัวออกแล้วใช้รูปเริ่มต้นใช่หรือไม่?")) {
      return;
    }

    setIsUploadingImage(true);
    try {
      await axios.post(`${Myhostlocalapi}/api/users/profile-image`, {
        userId: currentUser.userId || currentUser.UserID,
        empCode: empCode,
        username: currentUser.username,
        profileImage: null
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });

      setProfileImage(null);

      const updatedUser = { ...currentUser, profileImage: null };
      localStorage.setItem('user', JSON.stringify(updatedUser));
      if (setUser) setUser(updatedUser);
      window.dispatchEvent(new Event('user-profile-updated'));

      alert("ลบรูปส่วนตัวเรียบร้อยแล้ว");
    } catch (err) {
      console.error("Remove profile image error:", err);
      alert("เกิดข้อผิดพลาดในการลบรูปโปรไฟล์");
    } finally {
      setIsUploadingImage(false);
    }
  };

  const handleSaveNotifySettings = async (overrideData = {}) => {
    if (!empCode) return;
    setIsUpdatingNotify(true);
    setNotifyFeedback(null);
    try {
      const payload = {
        empCode,
        isLineNotifyEnabled: overrideData.isLineNotifyEnabled !== undefined ? overrideData.isLineNotifyEnabled : isLineNotifyEnabled,
        notifyTime: overrideData.notifyTime !== undefined ? overrideData.notifyTime : notifyTime,
        notifyDaysBefore: overrideData.notifyDaysBefore !== undefined ? overrideData.notifyDaysBefore : notifyDaysBefore
      };
      const res = await axios.post(`${Myhostlocalapi}/api/employees/notify-settings`, payload, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      setNotifyFeedback({ type: 'success', text: res.data.message || 'บันทึกการตั้งค่าการแจ้งเตือนสำเร็จ' });
      setTimeout(() => setNotifyFeedback(null), 3500);
    } catch (err) {
      console.error("Error saving notify settings:", err);
      setNotifyFeedback({ type: 'error', text: 'เกิดข้อผิดพลาดในการบันทึกการแจ้งเตือน' });
    } finally {
      setIsUpdatingNotify(false);
    }
  };

  const handleToggleNotify = async () => {
    const nextStatus = !isLineNotifyEnabled;
    setIsLineNotifyEnabled(nextStatus);
    await handleSaveNotifySettings({ isLineNotifyEnabled: nextStatus });
  };

  const handleTestNotify = async () => {
    if (!empCode) return;
    setIsTestingNotify(true);
    setNotifyFeedback(null);
    try {
      const res = await axios.post(`${Myhostlocalapi}/api/employees/test-notify`, {
        empCode
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });
      if (res.data.success) {
        setNotifyFeedback({ type: 'success', text: '🔔 ส่งข้อความแจ้งเตือนทดสอบเข้า LINE ของคุณแล้ว!' });
      } else {
        setNotifyFeedback({ type: 'error', text: res.data.message || 'ไม่สามารถส่งข้อความได้' });
      }
    } catch (err) {
      setNotifyFeedback({ type: 'error', text: err.response?.data?.message || err.message });
    } finally {
      setIsTestingNotify(false);
    }
  };

  return (
    <div className="main-viewport">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header Cover Banner */}
        <div className="bg-gradient-to-r from-indigo-600 via-indigo-700 to-sky-600 rounded-3xl p-6 sm:p-8 text-white shadow-lg relative overflow-hidden">
          <div className="absolute -right-10 -bottom-10 w-44 h-44 bg-white/10 rounded-full blur-2xl pointer-events-none"></div>
          
          <div className="relative z-10 flex flex-col sm:flex-row items-center gap-6 text-center sm:text-left">
            {/* Avatar Profile Picture with Camera Overlay */}
            <div className="relative group shrink-0">
              <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center text-3xl sm:text-4xl font-bold border-2 border-white/40 shadow-xl overflow-hidden relative">
                {isUploadingImage ? (
                  <div className="flex flex-col items-center justify-center text-white">
                    <Loader2 className="w-7 h-7 animate-spin mb-1" />
                    <span className="text-[10px]">กำลังอัปเดต...</span>
                  </div>
                ) : profileImage ? (
                  <img 
                    src={profileImage} 
                    alt={currentUser.fullName || currentUser.username} 
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <span className="text-white drop-shadow">
                    {currentUser.username ? currentUser.username[0].toUpperCase() : 'U'}
                  </span>
                )}

                {/* Hover overlay with Camera */}
                {!isUploadingImage && (
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute inset-0 bg-slate-900/60 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center text-white cursor-pointer transition-all duration-200"
                    title="คลิกเพื่ออัปโหลด/เปลี่ยนรูปโปรไฟล์"
                  >
                    <Camera className="w-6 h-6 mb-1 text-white" />
                    <span className="text-[11px] font-semibold">เปลี่ยนรูป</span>
                  </button>
                )}
              </div>

              {/* Floating Camera Button on bottom-right */}
              {!isUploadingImage && (
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute -bottom-1.5 -right-1.5 bg-white text-indigo-600 hover:bg-slate-50 p-2 rounded-xl shadow-md border border-slate-200 cursor-pointer transition-transform hover:scale-110 flex items-center justify-center"
                  title="อัปโหลดรูปส่วนตัว"
                >
                  <Camera className="w-4 h-4" />
                </button>
              )}

              {/* Hidden file input */}
              <input 
                ref={fileInputRef}
                type="file" 
                accept="image/*" 
                className="hidden" 
                onChange={handleImageUpload}
                disabled={isUploadingImage}
              />
            </div>

            {/* Profile Info & Actions */}
            <div className="space-y-2 flex-1">
              <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2">
                <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">
                  {currentUser.fullName || currentUser.username || 'User Profile'}
                </h1>
                <span className="inline-flex items-center gap-1 px-3 py-1 bg-white/20 backdrop-blur-sm rounded-full text-xs font-semibold text-white border border-white/20">
                  <ShieldCheck className="w-3.5 h-3.5" />
                  {currentUser.role || 'USER'}
                </span>
              </div>
              <p className="text-indigo-100 text-sm">
                @{currentUser.username || 'username'} • รหัสพนักงาน: {empCode || '-'}
              </p>

              {/* Action Buttons for Avatar */}
              <div className="pt-2 flex flex-wrap items-center justify-center sm:justify-start gap-2">
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={isUploadingImage}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white/20 hover:bg-white/30 active:bg-white/40 text-white rounded-xl text-xs font-semibold backdrop-blur-md transition-all shadow-xs border border-white/20 cursor-pointer"
                >
                  <Upload className="w-3.5 h-3.5" />
                  <span>{profileImage ? 'เปลี่ยนรูปส่วนตัว' : 'เพิ่มรูปส่วนตัว'}</span>
                </button>

                {profileImage && (
                  <button
                    type="button"
                    onClick={handleRemoveImage}
                    disabled={isUploadingImage}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 bg-white/10 hover:bg-rose-500/80 active:bg-rose-600 text-rose-100 hover:text-white rounded-xl text-xs font-semibold backdrop-blur-md transition-all border border-white/10 cursor-pointer"
                    title="ลบรูปโปรไฟล์และกลับไปใช้ตัวอักษรเริ่มต้น"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                    <span>ลบรูป</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Profile Details Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Information Card */}
          <div className="bg-white rounded-2xl p-6 border border-slate-200/80 shadow-sm space-y-4">
            <h2 className="text-base font-semibold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-3">
              <User className="w-5 h-5 text-indigo-600" /> ข้อมูลทั่วไป (Personal Info)
            </h2>
            <div className="space-y-3.5 text-sm">
              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500 flex items-center gap-2">
                  <Hash className="w-4 h-4 text-slate-400" /> รหัสพนักงาน
                </span>
                <span className="font-semibold text-slate-800 bg-slate-100 px-2.5 py-1 rounded-lg">
                  {empCode || '-'}
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500 flex items-center gap-2">
                  <User className="w-4 h-4 text-slate-400" /> ชื่อ-นามสกุล
                </span>
                <span className="font-medium text-slate-800">
                  {currentUser.fullName || '-'}
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500 flex items-center gap-2">
                  <Building className="w-4 h-4 text-slate-400" /> แผนก (Department)
                </span>
                <span className="font-medium text-slate-800">
                  {currentUser.department_name || 'IT Department'}
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500 flex items-center gap-2">
                  <Briefcase className="w-4 h-4 text-slate-400" /> ตำแหน่ง / บทบาท
                </span>
                <span className="inline-flex items-center px-2.5 py-1 rounded-md text-xs font-semibold bg-indigo-50 text-indigo-700">
                  {currentUser.role || 'User'}
                </span>
              </div>
            </div>
          </div>

          {/* System & Status Card */}
          <div className="bg-white rounded-2xl p-6 border border-slate-200/80 shadow-sm space-y-4">
            <h2 className="text-base font-semibold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-3">
              <ShieldCheck className="w-5 h-5 text-emerald-600" /> สถานะระบบ (System Status)
            </h2>
            <div className="space-y-3.5 text-sm">
              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500">สถานะการใช้งาน</span>
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                  Active / พร้อมใช้งาน
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500">สิทธิ์การเข้าถึงข้อมูล</span>
                <span className="font-medium text-slate-800">
                  {currentUser.role === 'ADMIN' ? 'Full Access (สิทธิ์ผู้ดูแลระบบ)' : 'Standard User (ผู้ใช้งานทั่วไป)'}
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500">ความปลอดภัย</span>
                <span className="inline-flex items-center gap-1 text-xs text-slate-600 font-medium bg-slate-100 px-2.5 py-1 rounded-lg">
                  <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" /> ตรวจสอบสิทธิ์แล้ว
                </span>
              </div>

              <div className="flex justify-between items-center py-1">
                <span className="text-slate-500">ระบบเข้าสู่ระบบ</span>
                <span className="text-slate-700 font-medium">SHIFTPRO IT Portal</span>
              </div>
            </div>
          </div>
        </div>

        {/* Quick Shift Configuration Card */}
        {empDetails && (
          <div className="bg-white rounded-2xl p-6 border border-slate-200/80 shadow-sm space-y-4">
            <h2 className="text-base font-semibold text-slate-800 flex items-center gap-2 border-b border-slate-100 pb-3">
              <Calendar className="w-5 h-5 text-indigo-600" /> ข้อมูลการจัดกะประจำตัว (Personal Shift Configuration)
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5 pt-1">
              {/* Default Off */}
              <div className="p-3.5 bg-rose-50/70 rounded-xl border border-rose-100/80 flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg bg-rose-100 text-rose-700 flex items-center justify-center font-bold shrink-0">
                  <Coffee className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-[11px] text-slate-500 font-medium">วันหยุดประจำสัปดาห์</span>
                  <div className="text-sm font-bold text-rose-700">
                    {empDetails.DefaultOffDay !== null && empDetails.DefaultOffDay !== undefined
                      ? `วัน${['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'][empDetails.DefaultOffDay]}`
                      : 'ยังไม่กำหนด'}
                  </div>
                </div>
              </div>

              {/* Default WFH */}
              <div className="p-3.5 bg-sky-50/70 rounded-xl border border-sky-100/80 flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg bg-sky-100 text-sky-700 flex items-center justify-center font-bold shrink-0">
                  <Home className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-[11px] text-slate-500 font-medium">วัน WFH ประจำสัปดาห์</span>
                  <div className="text-sm font-bold text-sky-700">
                    {empDetails.DefaultWfhDay !== null && empDetails.DefaultWfhDay !== undefined
                      ? `วัน${['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'][empDetails.DefaultWfhDay]}`
                      : 'ยังไม่กำหนด'}
                  </div>
                </div>
              </div>

              {/* Locked 9AM */}
              <div className="p-3.5 bg-indigo-50/70 rounded-xl border border-indigo-100/80 flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg bg-indigo-100 text-indigo-700 flex items-center justify-center font-bold shrink-0">
                  <Clock className="w-4 h-4" />
                </div>
                <div>
                  <span className="text-[11px] text-slate-500 font-medium">สถานะกะ 9 โมง (F13)</span>
                  <div className="text-sm font-bold text-indigo-700">
                    {empDetails.IsLocked9Am ? 'ประจำกะ 9:00 - 18:00' : 'กะปกติ (หมุนเวียน)'}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* LINE Notification Settings Card */}
        <div className="bg-white rounded-2xl p-5 sm:p-6 border border-slate-200/80 shadow-sm space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-base font-semibold text-slate-800 flex items-center gap-2">
                <Bell className="w-5 h-5 text-indigo-600" /> การแจ้งเตือนตารางงานผ่าน LINE (LINE Notifications)
              </h2>
              <p className="text-xs text-slate-500">
                กำหนดเวลาและวันที่ที่ต้องการให้บอท LINE ส่งสรุปกะงานและเวรเที่ยงให้คุณแบบอัตโนมัติ
              </p>
            </div>

            <div className="flex items-center gap-3">
              <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${
                isLineNotifyEnabled 
                  ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' 
                  : 'bg-slate-100 text-slate-500 border border-slate-200'
              }`}>
                {isLineNotifyEnabled ? 'เปิดรับการแจ้งเตือน' : 'ปิดการแจ้งเตือน'}
              </span>

              {/* Toggle Switch */}
              <button
                type="button"
                onClick={handleToggleNotify}
                disabled={isUpdatingNotify || !empCode}
                className={`relative inline-flex h-7 w-14 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:ring-offset-2 ${
                  isLineNotifyEnabled ? 'bg-indigo-600' : 'bg-slate-200'
                }`}
                title="คลิกเพื่อ เปิด/ปิด การแจ้งเตือนอัตโนมัติ"
              >
                <span
                  className={`pointer-events-none inline-block h-6 w-6 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out flex items-center justify-center ${
                    isLineNotifyEnabled ? 'translate-x-7' : 'translate-x-0'
                  }`}
                >
                  {isLineNotifyEnabled ? (
                    <Bell className="w-3.5 h-3.5 text-indigo-600" />
                  ) : (
                    <BellOff className="w-3.5 h-3.5 text-slate-400" />
                  )}
                </span>
              </button>
            </div>
          </div>

          {/* Feedback Banner */}
          {notifyFeedback && (
            <div className={`p-3 rounded-xl text-xs font-semibold flex items-center gap-2 ${
              notifyFeedback.type === 'success' 
                ? 'bg-emerald-50 text-emerald-800 border border-emerald-200' 
                : 'bg-rose-50 text-rose-800 border border-rose-200'
            }`}>
              {notifyFeedback.type === 'success' ? <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" /> : <BellOff className="w-4 h-4 text-rose-600 shrink-0" />}
              <span>{notifyFeedback.text}</span>
            </div>
          )}

          {isLineNotifyEnabled && (
            <div className="pt-2 border-t border-slate-100 space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Choose Timing */}
                <div className="space-y-1.5">
                  <label className="block text-xs font-bold text-slate-700">
                    📅 ต้องการรับแจ้งเตือนวันไหน:
                  </label>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <label className={`p-2.5 rounded-xl border cursor-pointer transition-all flex items-center gap-2 ${
                      notifyDaysBefore === 1 
                        ? 'bg-indigo-50 border-indigo-400 text-indigo-900 font-bold' 
                        : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'
                    }`}>
                      <input
                        type="radio"
                        name="profileNotifyDays"
                        value={1}
                        checked={notifyDaysBefore === 1}
                        onChange={() => setNotifyDaysBefore(1)}
                        className="text-indigo-600"
                      />
                      <div>
                        <div>ล่วงหน้า 1 วัน</div>
                        <div className="text-[10px] font-normal text-slate-400">(กะวันพรุ่งนี้)</div>
                      </div>
                    </label>

                    <label className={`p-2.5 rounded-xl border cursor-pointer transition-all flex items-center gap-2 ${
                      notifyDaysBefore === 0 
                        ? 'bg-indigo-50 border-indigo-400 text-indigo-900 font-bold' 
                        : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'
                    }`}>
                      <input
                        type="radio"
                        name="profileNotifyDays"
                        value={0}
                        checked={notifyDaysBefore === 0}
                        onChange={() => setNotifyDaysBefore(0)}
                        className="text-indigo-600"
                      />
                      <div>
                        <div>วันเดียวกัน</div>
                        <div className="text-[10px] font-normal text-slate-400">(กะวันนี้)</div>
                      </div>
                    </label>
                  </div>
                </div>

                {/* Choose Time */}
                <div className="space-y-1.5">
                  <div className="flex justify-between items-center">
                    <label className="block text-xs font-bold text-slate-700">
                      ⏰ เวลาที่ต้องการรับแจ้งเตือน:
                    </label>
                    <span className="text-xs font-mono font-bold text-indigo-700 bg-indigo-50 px-2 py-0.5 rounded-lg border border-indigo-100">
                      {notifyTime} น.
                    </span>
                  </div>
                  <input
                    type="time"
                    value={notifyTime}
                    onChange={(e) => setNotifyTime(e.target.value)}
                    className="w-full p-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-slate-800 text-center focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  />
                  <div className="flex flex-wrap items-center gap-1">
                    {['06:30', '07:00', '08:00', '18:00', '19:00', '20:00', '21:00'].map(t => (
                      <button
                        key={t}
                        type="button"
                        onClick={() => setNotifyTime(t)}
                        className={`px-2 py-0.5 rounded-lg text-[11px] font-semibold transition-all ${
                          notifyTime === t ? 'bg-indigo-600 text-white' : 'bg-slate-100 hover:bg-slate-200 text-slate-600'
                        }`}
                      >
                        {t}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              <div className="flex flex-col sm:flex-row items-center gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => handleSaveNotifySettings()}
                  disabled={isUpdatingNotify}
                  className="w-full sm:w-auto px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-semibold text-xs sm:text-sm shadow-xs transition-colors cursor-pointer"
                >
                  {isUpdatingNotify ? 'กำลังบันทึก...' : '💾 บันทึกเวลาแจ้งเตือน'}
                </button>

                <button
                  type="button"
                  onClick={handleTestNotify}
                  disabled={isTestingNotify}
                  className="w-full sm:w-auto px-4 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-semibold text-xs sm:text-sm transition-colors cursor-pointer flex items-center justify-center gap-1.5"
                >
                  <Bell className="w-3.5 h-3.5 text-indigo-600" />
                  <span>{isTestingNotify ? 'กำลังส่งทดสอบ...' : '🔔 ทดสอบส่งเข้า LINE ตอนนี้'}</span>
                </button>
              </div>
            </div>
          )}
          
          <div className="text-xs text-slate-500 bg-slate-50 p-3.5 rounded-xl border border-slate-100 flex items-start gap-2">
            <span className="font-bold text-slate-700">💡 ทริค:</span>
            <span>
              คุณสามารถพิมพ์คำว่า <b>"ปิดแจ้งเตือน"</b> หรือ <b>"เปิดแจ้งเตือน"</b> ในแชท LINE กับบอทของระบบเพื่อตั้งค่าได้ทันทีเช่นกัน
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
