import React, { useState } from 'react';
import axios from 'axios';
import { Myhostlocalapi } from './../Myhostlocalapi';
import { 
  Shield, 
  KeyRound, 
  Lock, 
  Check, 
  Eye, 
  EyeOff, 
  AlertCircle, 
  CheckCircle2, 
  Loader2,
  ShieldAlert,
  UserCheck
} from 'lucide-react';

export default function AccountView({ user }) {
  const currentUser = user || JSON.parse(localStorage.getItem('user')) || {};

  // Form State สำหรับเปลี่ยนรหัสผ่าน
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [showCurrentPass, setShowCurrentPass] = useState(false);
  const [showNewPass, setShowNewPass] = useState(false);
  const [showConfirmPass, setShowConfirmPass] = useState(false);

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });

  // ตรวจสอบความปลอดภัยของรหัสผ่านใหม่ (Password Strength)
  const getPasswordStrength = (pass) => {
    if (!pass) return { score: 0, label: '', color: 'bg-slate-200' };
    let score = 0;
    if (pass.length >= 6) score += 1;
    if (pass.length >= 8) score += 1;
    if (/[A-Z]/.test(pass) || /[0-9]/.test(pass)) score += 1;
    if (/[^A-Za-z0-9]/.test(pass)) score += 1;

    if (score <= 1) return { score: 1, label: 'ระดับง่าย (Weak)', color: 'bg-rose-500', width: '25%' };
    if (score === 2) return { score: 2, label: 'ปานกลาง (Medium)', color: 'bg-amber-500', width: '50%' };
    if (score === 3) return { score: 3, label: 'ปลอดภัยดี (Good)', color: 'bg-sky-500', width: '75%' };
    return { score: 4, label: 'ปลอดภัยสูง (Strong)', color: 'bg-emerald-500', width: '100%' };
  };

  const strength = getPasswordStrength(newPassword);

  const handleChangePassword = async (e) => {
    e.preventDefault();
    setMessage({ type: '', text: '' });

    if (!currentPassword || !newPassword || !confirmPassword) {
      setMessage({ type: 'error', text: 'กรุณากรอกข้อมูลให้ครบทุกช่อง' });
      return;
    }

    if (newPassword.length < 4) {
      setMessage({ type: 'error', text: 'รหัสผ่านใหม่ต้องมีความยาวอย่างน้อย 4 ตัวอักษร' });
      return;
    }

    if (newPassword !== confirmPassword) {
      setMessage({ type: 'error', text: 'รหัสผ่านใหม่และยืนยันรหัสผ่านไม่ตรงกัน' });
      return;
    }

    if (newPassword === currentPassword) {
      setMessage({ type: 'error', text: 'รหัสผ่านใหม่ต้องไม่ซ้ำกับรหัสผ่านเดิม' });
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post(`${Myhostlocalapi}/api/users/change-password`, {
        userId: currentUser.userId || currentUser.UserID,
        username: currentUser.username,
        currentPassword,
        newPassword
      }, {
        headers: { 'ngrok-skip-browser-warning': '69420' }
      });

      if (res.data.success) {
        setMessage({ type: 'success', text: 'เปลี่ยนรหัสผ่านสำเร็จเรียบร้อยแล้ว!' });
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
      } else {
        setMessage({ type: 'error', text: res.data.message || 'ไม่สามารถเปลี่ยนรหัสผ่านได้' });
      }
    } catch (err) {
      setMessage({
        type: 'error',
        text: err.response?.data?.message || err.response?.data?.error || 'เกิดข้อผิดพลาดในการเปลี่ยนรหัสผ่าน'
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="main-viewport">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-2 border-b border-slate-200">
          <div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight flex items-center gap-2">
              <Shield className="w-6 h-6 text-indigo-600" /> การตั้งค่าบัญชี (Account Settings)
            </h1>
            <p className="text-sm text-slate-500 mt-1">
              จัดการความปลอดภัย รหัสผ่าน และข้อมูลบัญชีผู้ใช้งานของคุณ
            </p>
          </div>
        </div>

        {/* Account Info Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Card 1: Account Overview */}
          <div className="bg-white rounded-2xl p-6 border border-slate-200/80 shadow-sm space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                <Lock className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-semibold text-slate-800 text-sm">ข้อมูลล็อกอิน (Authentication)</h3>
                <p className="text-xs text-slate-500">บัญชีสำหรับเข้าสู่ระบบ ShiftPro</p>
              </div>
            </div>

            <div className="space-y-3 pt-2 text-sm">
              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center">
                <span className="text-xs text-slate-500">Username</span>
                <span className="font-semibold text-slate-800">{currentUser.username || '-'}</span>
              </div>
              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center">
                <span className="text-xs text-slate-500">รหัสพนักงานผูกบัญชี</span>
                <span className="font-semibold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md border border-indigo-100 text-xs">
                  {currentUser.empCode || currentUser.EmpCode || 'ยังไม่ได้ผูก'}
                </span>
              </div>
              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center">
                <span className="text-xs text-slate-500">ระดับสิทธิ์ (Role)</span>
                <span className="text-xs font-bold text-indigo-700 bg-indigo-50 px-2.5 py-0.5 rounded-full border border-indigo-200">
                  {currentUser.role || 'User'}
                </span>
              </div>
            </div>
          </div>

          {/* Card 2: Security & Session Status */}
          <div className="bg-white rounded-2xl p-6 border border-slate-200/80 shadow-sm space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center font-bold">
                <KeyRound className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-semibold text-slate-800 text-sm">ความปลอดภัย (Security Status)</h3>
                <p className="text-xs text-slate-500">สถานะการเชื่อมต่อและการป้องกันข้อมูล</p>
              </div>
            </div>

            <div className="space-y-3 pt-2 text-sm">
              <div className="flex items-start gap-3 p-3 bg-emerald-50/70 rounded-xl border border-emerald-100 text-xs text-emerald-900">
                <Check className="w-4 h-4 text-emerald-600 flex-shrink-0 mt-0.5" />
                <span>การเชื่อมต่อปลอดภัยผ่านระบบเข้ารหัสและสิทธิ์ Role-Based Access Control (RBAC)</span>
              </div>

              <div className="flex items-start gap-3 p-3 bg-indigo-50/70 rounded-xl border border-indigo-100 text-xs text-indigo-900">
                <UserCheck className="w-4 h-4 text-indigo-600 flex-shrink-0 mt-0.5" />
                <span>ผู้ใช้งานสามารถเปลี่ยนรหัสผ่านของตนเองได้ตลอดเวลาผ่านแบบฟอร์มด้านล่างนี้</span>
              </div>
            </div>
          </div>
        </div>

        {/* Change Password Form Card */}
        <div className="bg-white rounded-2xl p-6 sm:p-7 border border-slate-200/80 shadow-sm space-y-5">
          <div className="flex items-center gap-3 border-b border-slate-100 pb-4">
            <div className="w-10 h-10 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center font-bold">
              <ShieldAlert className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-bold text-slate-900 text-base">เปลี่ยนรหัสผ่าน (Change Password)</h2>
              <p className="text-xs text-slate-500">เพื่อความปลอดภัย แนะนำให้เปลี่ยนรหัสผ่านอย่างสม่ำเสมอ</p>
            </div>
          </div>

          {/* Feedback Alert Message */}
          {message.text && (
            <div className={`p-4 rounded-xl text-xs sm:text-sm font-medium flex items-center gap-2.5 transition-all ${
              message.type === 'success' 
                ? 'bg-emerald-50 border border-emerald-200 text-emerald-800' 
                : 'bg-rose-50 border border-rose-200 text-rose-800'
            }`}>
              {message.type === 'success' ? (
                <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
              ) : (
                <AlertCircle className="w-4 h-4 text-rose-600 flex-shrink-0" />
              )}
              <span>{message.text}</span>
            </div>
          )}

          <form onSubmit={handleChangePassword} className="space-y-4 max-w-xl">
            {/* Input: Current Password */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1.5">
                รหัสผ่านปัจจุบัน (Current Password) *
              </label>
              <div className="relative">
                <input 
                  type={showCurrentPass ? 'text' : 'password'}
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  placeholder="กรอกรหัสผ่านปัจจุบันของคุณ"
                  required
                  className="w-full pl-3.5 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                />
                <button
                  type="button"
                  onClick={() => setShowCurrentPass(!showCurrentPass)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                  title={showCurrentPass ? 'ซ่อนรหัสผ่าน' : 'แสดงรหัสผ่าน'}
                >
                  {showCurrentPass ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            {/* Input: New Password */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1.5">
                รหัสผ่านใหม่ (New Password) *
              </label>
              <div className="relative">
                <input 
                  type={showNewPass ? 'text' : 'password'}
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  placeholder="อย่างน้อย 4 ตัวอักษร"
                  required
                  className="w-full pl-3.5 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                />
                <button
                  type="button"
                  onClick={() => setShowNewPass(!showNewPass)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                  title={showNewPass ? 'ซ่อนรหัสผ่าน' : 'แสดงรหัสผ่าน'}
                >
                  {showNewPass ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>

              {/* Password Strength Indicator */}
              {newPassword && (
                <div className="mt-2 space-y-1">
                  <div className="w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-300 ${strength.color}`} 
                      style={{ width: strength.width }}
                    ></div>
                  </div>
                  <div className="flex justify-between items-center text-[10px] text-slate-400">
                    <span>ความปลอดภัยรหัสผ่าน: <b className="text-slate-700">{strength.label}</b></span>
                    <span>แนะนำ 8 ตัวอักษรขึ้นไป</span>
                  </div>
                </div>
              )}
            </div>

            {/* Input: Confirm New Password */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 mb-1.5">
                ยืนยันรหัสผ่านใหม่ (Confirm New Password) *
              </label>
              <div className="relative">
                <input 
                  type={showConfirmPass ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="กรอกรหัสผ่านใหม่อีกครั้ง"
                  required
                  className="w-full pl-3.5 pr-10 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPass(!showConfirmPass)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                  title={showConfirmPass ? 'ซ่อนรหัสผ่าน' : 'แสดงรหัสผ่าน'}
                >
                  {showConfirmPass ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
              {confirmPassword && newPassword !== confirmPassword && (
                <p className="text-[11px] text-rose-500 mt-1">
                  * รหัสผ่านใหม่และยืนยันรหัสผ่านยังไม่ตรงกัน
                </p>
              )}
            </div>

            {/* Submit Button */}
            <div className="pt-2">
              <button
                type="submit"
                disabled={loading}
                className="inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white rounded-xl text-xs sm:text-sm font-semibold shadow-sm shadow-indigo-500/20 transition-all cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    <span>กำลังบันทึกรหัสผ่านใหม่...</span>
                  </>
                ) : (
                  <>
                    <KeyRound className="w-4 h-4" />
                    <span>บันทึกรหัสผ่านใหม่</span>
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
